    /**
     * Connects the password visibility toggle of a {@link TextInputLayout} to both the password
     * input it wraps and a separate confirmation input placed outside of it.
     *
     * The default toggle only knows about the {@code EditText} that is a child of the
     * {@code TextInputLayout}, so the confirmation field would otherwise stay masked.
     *
     * Both inputs start out masked, matching the state of the toggle.
     */
    public static void setupPasswordVisibilityToggle(final TextInputLayout passwordLayout, final EditText passwordInput, final EditText passwordConfirm) {
        passwordLayout.setEndIconOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                boolean wasHidden = passwordInput.getTransformationMethod() instanceof PasswordTransformationMethod;

                // Dispatch the visibility change to both the password and the confirmation input
                dispatchPasswordVisibilityChange(passwordInput, wasHidden);
                dispatchPasswordVisibilityChange(passwordConfirm, wasHidden);

                passwordLayout.refreshDrawableState();
            }
        });

        passwordInput.setTransformationMethod(PasswordTransformationMethod.getInstance());
        passwordConfirm.setTransformationMethod(PasswordTransformationMethod.getInstance());
    }

    private static void dispatchPasswordVisibilityChange(EditText editText, boolean wasHidden) {
        // Changing the transformation method resets the cursor position, so restore it afterwards
        final int selection = editText.getSelectionEnd();

        if (wasHidden)
            editText.setTransformationMethod(null);
        else
            editText.setTransformationMethod(PasswordTransformationMethod.getInstance());

        if (selection >= 0)
            editText.setSelection(selection);
    }
}

