152	    private void encryptAndPersist(String value) {
153	        try {
154	            byte[] encBytes = EncryptionHelper.encrypt(key.getPublic(), value.getBytes(StandardCharsets.UTF_8));
155	            persistString(Base64.encodeToString(encBytes, Base64.URL_SAFE));
156	        } catch (Exception e) {
157	            e.printStackTrace();
158	        }
159	    }
160	
161	    private void restoreAndDecrypt(String encValue) {
162	        try {
163	            byte[] encBytes = Base64.decode(encValue, Base64.URL_SAFE);
164	            value = new String(EncryptionHelper.decrypt(key.getPrivate(), encBytes), StandardCharsets.UTF_8);
165	        } catch (Exception e) {
166	            e.printStackTrace();
167	        }
168	    }
169	
170	    @Override
171	    protected void onSetInitialValue(boolean restorePersistedValue, Object defaultValue) {
172	        if (restorePersistedValue) {
173	            restoreAndDecrypt(getPersistedString(DEFAULT_VALUE));
174	        } else {
175	            value = (String) defaultValue;
176	            encryptAndPersist(value);
177	        }
178	    }
